// Photo storage. Today: local disk. Later: replace these three functions with an
// S3-compatible bucket (the rest of the app only calls save / remove / urlFor).
const fs = require('fs/promises');
const path = require('path');
const config = require('./config');

const root = path.resolve(config.uploadDir);

// Keys are always generated by the server, but we still refuse anything that
// would escape the upload folder.
function resolveKey(key) {
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error('Invalid storage key');
  return full;
}

async function save(key, buffer) {
  const full = resolveKey(key);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, buffer);
}

async function remove(key) {
  await fs.rm(resolveKey(key), { force: true });
}

const urlFor = (key) => `${config.publicBaseUrl}/uploads/${key}`;

module.exports = { root, save, remove, urlFor };
